// Wire contract of the controller role (CHAOS-115, ADR-017).
//
// Mirrors `packages/protocol/src/schemas.ts` (protocol v4) for every message a controller
// sends or receives. Field names and JSON shapes are identical to the zod schemas; the
// fixture corpus in `Tests/Fixtures` (generated by `scripts/export-protocol-fixtures.ts`)
// proves it. Validation is deliberately light: the server is the trust boundary.
//
// Deliberate leniencies compared with zod (forward compatibility, see ADR-017):
// - unknown message `type` decodes to `.unknown(type:)` instead of failing,
// - enum-like fields are open string structs: unknown values decode instead of failing,
// - unknown object keys are ignored (zod `strictObject` rejects them).
import Foundation

// MARK: - Constants (schemas.ts, version.ts, players.ts)

enum ProtocolConstants {
    /// `PROTOCOL_VERSION` in `version.ts`.
    static let version = 4
    /// Largest client message as JSON text (UTF-16 units, like JS `string.length`).
    static let maxMessageLength = 4096
    /// Largest server message as JSON text.
    static let maxServerMessageLength = 65_536
    static let stickEpsilon = 0.001
    static let maxNameLength = 16
    static let maxErrorMessageLength = 200
    static let maxPlayers = 4
    /// `MINIGAME_KOOP_MAX_TIER`: highest koop tier (CHAOS-89).
    static let minigameKoopMaxTier = 3
    /// Close code: the slots were taken over by another connection via `reconnect`.
    static let closeReplaced = 4003
}

// MARK: - Open string enums

/// String-valued enum that accepts unknown values (forward compatible). `known` lists the
/// values of the matching TS constant array and is checked against the fixture corpus.
protocol OpenStringEnum: RawRepresentable, Codable, Hashable, Sendable,
    ExpressibleByStringLiteral where RawValue == String
{
    init(rawValue: String)
    static var known: [Self] { get }
}

extension OpenStringEnum {
    init(stringLiteral value: String) { self.init(rawValue: value) }
    var isKnown: Bool { Self.known.contains(self) }
}

/// `PHASES`
struct Phase: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let lobby: Self = "lobby", play: Self = "play", board: Self = "board"
    static let known: [Self] = [.lobby, .play, .board]
}

/// `LAYOUTS`
struct Layout: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let wait: Self = "wait", lobby: Self = "lobby"
    static let joystickButtons: Self = "joystick-buttons", board: Self = "board"
    static let known: [Self] = [.wait, .lobby, .joystickButtons, .board]
}

/// `ACTIONS`: what a slot may do in the current context.
struct Action: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let ready: Self = "ready", move: Self = "move"
    static let buttonA: Self = "button-a", buttonB: Self = "button-b"
    static let gesture: Self = "gesture", reaction: Self = "reaction", choose: Self = "choose"
    static let pickCharacter: Self = "pick-character"
    /// Thumbs up/down after a minigame (CHAOS-87; native UI: CHAOS-219).
    static let rate: Self = "rate"
    static let known: [Self] = [
        .ready, .move, .buttonA, .buttonB, .gesture, .reaction, .choose, .pickCharacter, .rate,
    ]
}

/// `FEEDBACK_KINDS`
struct FeedbackKind: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let confirm: Self = "confirm", hit: Self = "hit", miss: Self = "miss"
    static let win: Self = "win", lose: Self = "lose"
    static let known: [Self] = [.confirm, .hit, .miss, .win, .lose]
}

/// `ERROR_CODES` (wire codes only; client-side codes live in `UiErrorCode`).
struct ErrorCode: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let badMessage: Self = "bad-message", tooLarge: Self = "too-large"
    static let versionMismatch: Self = "version-mismatch", notJoined: Self = "not-joined"
    static let badJoinCode: Self = "bad-join-code", sessionFull: Self = "session-full"
    static let badToken: Self = "bad-token", hostTaken: Self = "host-taken"
    static let notYourSlot: Self = "not-your-slot", outOfPhase: Self = "out-of-phase"
    static let staleSeq: Self = "stale-seq", rateLimited: Self = "rate-limited"
    static let invalidChoice: Self = "invalid-choice", invalidResult: Self = "invalid-result"
    static let characterTaken: Self = "character-taken", paused: Self = "paused"
    static let `internal`: Self = "internal"
    static let known: [Self] = [
        .badMessage, .tooLarge, .versionMismatch, .notJoined, .badJoinCode, .sessionFull,
        .badToken, .hostTaken, .notYourSlot, .outOfPhase, .staleSeq, .rateLimited,
        .invalidChoice, .invalidResult, .characterTaken, .paused, .internal,
    ]
}

/// `GAME_PHASES`
struct GamePhase: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let setup: Self = "setup", turnStart: Self = "turn-start", roll: Self = "roll"
    static let chooseTarget: Self = "choose-target", move: Self = "move"
    static let choosePath: Self = "choose-path", trophyOffer: Self = "trophy-offer"
    static let spaceEvent: Self = "space-event", reactionWindow: Self = "reaction-window"
    static let turnEnd: Self = "turn-end", minigameIntro: Self = "minigame-intro"
    static let minigamePlay: Self = "minigame-play", minigameResults: Self = "minigame-results"
    static let roundEnd: Self = "round-end", gameResults: Self = "game-results"
    static let known: [Self] = [
        .setup, .turnStart, .roll, .chooseTarget, .move, .choosePath, .trophyOffer,
        .spaceEvent, .reactionWindow, .turnEnd, .minigameIntro, .minigamePlay,
        .minigameResults, .roundEnd, .gameResults,
    ]
}

/// `ITEM_KINDS`
struct ItemKind: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let doubleDice: Self = "double-dice", coinSteal: Self = "coin-steal"
    static let trap: Self = "trap", shield: Self = "shield"
    static let known: [Self] = [.doubleDice, .coinSteal, .trap, .shield]
}

/// `PROMPT_KINDS`. Unknown kinds render as a plain button list (`board/prompt.ts`).
struct PromptKind: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let roll: Self = "roll", target: Self = "target", path: Self = "path"
    static let trophy: Self = "trophy", reaction: Self = "reaction"
    static let known: [Self] = [.roll, .target, .path, .trophy, .reaction]
}

/// `CHARACTER_IDS` (`characters.ts`), fixed order: slot n defaults to the n-th.
struct CharacterId: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let robot: Self = "robot", cactus: Self = "cactus"
    static let raccoon: Self = "raccoon", sock: Self = "sock"
    static let known: [Self] = [.robot, .cactus, .raccoon, .sock]

    /// `CHARACTER_NAMES`: display name and blurb (German UI text).
    var displayName: String {
        switch self {
        case .robot: "Schraubi"
        case .cactus: "Kalle Kaktus"
        case .raccoon: "Wusel"
        case .sock: "Socke Sigi"
        default: rawValue
        }
    }

    var blurb: String {
        switch self {
        case .robot: "Aufzieh-Roboter mit Wackelantenne"
        case .cactus: "Stacheliger Coolmann mit Sonnenbrille"
        case .raccoon: "Waschbär mit Diebesmaske und Ringelschwanz"
        case .sock: "Einzelsocke auf der Suche nach Ruhm"
        default: ""
        }
    }
}

/// `MINIGAME_STAGES`
struct MinigameStage: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let intro: Self = "intro", play: Self = "play", results: Self = "results"
    static let known: [Self] = [.intro, .play, .results]
}

/// `VOTES`: thumbs after a minigame (CHAOS-87). Open because it also arrives in
/// `minigame.vote`; the app only sends `up` and `down`.
struct Vote: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let up: Self = "up", down: Self = "down"
    static let known: [Self] = [.up, .down]
}

/// `MINIGAME_TEAM_LAYOUTS` (CHAOS-89): line-up of a team or koop minigame.
struct MinigameTeamLayout: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let oneVsThree: Self = "1v3", twoVsTwo: Self = "2v2", oneVsTwo: Self = "1v2"
    static let oneVsOne: Self = "1v1", koop: Self = "koop"
    static let known: [Self] = [.oneVsThree, .twoVsTwo, .oneVsTwo, .oneVsOne, .koop]
}

/// `ControllerMinigameTeamSchema.role`: alone, in a team, or everybody together.
struct MinigameTeamRole: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let solo: Self = "solo", team: Self = "team", koop: Self = "koop"
    static let known: [Self] = [.solo, .team, .koop]
}

/// `ControllerMinigameTeamSchema.result`: own team's outcome (not for koop).
struct MinigameTeamResult: OpenStringEnum {
    let rawValue: String
    init(rawValue: String) { self.rawValue = rawValue }
    static let won: Self = "won", lost: Self = "lost", draw: Self = "draw"
    static let known: [Self] = [.won, .lost, .draw]
}

/// `BUTTONS` (outbound only, therefore closed).
enum Button: String, Codable, CaseIterable, Sendable {
    case a, b
}

/// `GESTURE_KINDS` (outbound only; the web controller never sends gestures today).
enum GestureKind: String, Codable, CaseIterable, Sendable {
    case swipeUp = "swipe-up", swipeDown = "swipe-down"
    case swipeLeft = "swipe-left", swipeRight = "swipe-right"
}

// MARK: - Server → Controller payloads

/// `PlayerInfoSchema`
struct PlayerInfo: Codable, Equatable, Sendable {
    var slot: Int
    /// `#RRGGBB`
    var color: String
    var label: String
}

/// `WelcomeMessageSchema`
struct Welcome: Codable, Equatable, Sendable {
    var sessionToken: String
    var players: [PlayerInfo]
}

/// `PromptOptionSchema`
struct PromptOption: Codable, Equatable, Sendable {
    /// Goes back verbatim in `choose { option }`.
    var id: String
    var label: String
    var detail: String?
    var slot: Int?
}

/// `PromptSchema`: a decision this slot has to make (board phase).
struct Prompt: Codable, Equatable, Sendable {
    var id: Int
    var slot: Int
    var kind: PromptKind
    var title: String
    var options: [PromptOption]
    /// Remaining time when sent (ms), `nil` = unlimited. Nullable on the wire.
    var remainingMs: Int?
}

/// `ControllerBoardInfoSchema`: own status during the board phase.
struct ControllerBoardInfo: Codable, Equatable, Sendable {
    var gamePhase: GamePhase
    var round: Int
    var rounds: Int
    var coins: Int
    var trophies: Int
    var items: [ItemKind]
    /// Whose turn it is; nullable on the wire (`null` during minigames/results).
    var activeSlot: Int?
    /// Final place, only in `game-results`.
    var place: Int?
    var paused: Bool
    var character: CharacterId
    var minigameWins: Int
    var tied: Bool?
    var endedEarly: Bool?
    /// Own tailwind coins after the minigame, only in `round-end` (CHAOS-125); `nil` = none.
    var tailwind: Int?
}

/// `MinigameControlsSchema`: label per control, `nil` (wire `null`) = not offered.
struct MinigameControls: Codable, Equatable, Sendable {
    var joystick: String?
    var a: String?
    var b: String?
}

/// `MinigameCueSchema` (v4 addendum CHAOS-231): cue of the running section of a minigame
/// (Schnellfeuer: micro game `step` of `steps`) with its picture word and only its controls.
struct MinigameCue: Codable, Equatable, Sendable {
    var step: Int
    var steps: Int
    var icon: String
    var word: String
    var controls: MinigameControls
    /// The section counts double (Schnellfeuer finale, „×2“).
    var double: Bool
}

/// `ControllerMinigameTeamSchema` (v4 addendum CHAOS-89, Swift: CHAOS-229): own role in a
/// team or koop minigame, from the intro on; `result`/`tier` only in `results`.
struct ControllerMinigameTeam: Codable, Equatable, Sendable {
    var layout: MinigameTeamLayout
    var role: MinigameTeamRole
    /// Own team (marks like on the PC: 0 = ☀ Sonne, 1 = ☾ Mond).
    var index: Int
    var mates: [Int]
    var opponents: [Int]
    /// With three players the single person has an advantage in the game.
    var advantage: Bool
    /// Only in `results`: own team won, lost or drew (not in koop).
    var result: MinigameTeamResult?
    /// Only in `results` for koop: reached tier 0–3.
    var tier: Int?
}

/// `ControllerMinigameInfoSchema`
struct ControllerMinigameInfo: Codable, Equatable, Sendable {
    var id: String
    var title: String
    var tagline: String
    var instructions: [String]
    var controls: MinigameControls
    var stage: MinigameStage
    var place: Int?
    var score: Int?
    var scoreUnit: String
    var tied: Bool
    var aborted: Bool
    var reward: Int?
    /// v4 addendum (CHAOS-51, EXP-019): items won with the result (consolation prize), only
    /// in `results`; missing when there are none (1–4 entries on the wire).
    var prizes: [ItemKind]?
    /// v4 addendum (CHAOS-66, optional): the minigame already ran this match, so the intro
    /// shows title and controls only. Missing = `false` (full instructions).
    var `repeat`: Bool?
    /// v4 addendum (CHAOS-214, optional): only in `intro` while the intro waits for „Bereit“:
    /// `true` = this slot already pressed it. Missing = the intro does not wait (fixed timer,
    /// older servers): no button.
    var ready: Bool?
    /// v4 addendum (CHAOS-87, optional): practice round from the minigame gallery (no coins,
    /// back to the lobby afterwards). Missing = `false`.
    var practice: Bool?
    /// v4 addendum (CHAOS-87, optional), only in `results`: own thumbs vote for this run.
    /// Missing = not voted yet. Voting is possible while `actions` contains `rate`.
    var vote: Vote?
    /// v4 addendum (CHAOS-231, optional), only in `play`: picture word and controls of the running
    /// section. Missing = no sections or an older host; then `controls` apply.
    var cue: MinigameCue?
    /// v4 addendum (CHAOS-89, optional): own role in a team or koop minigame. Missing = every
    /// player for themselves (and older servers): no role card, no team outcome.
    var team: ControllerMinigameTeam?
}

/// Element of `ControllerLobbyInfoSchema.takenBy`.
struct TakenCharacter: Codable, Equatable, Sendable {
    var character: CharacterId
    var slot: Int
}

/// `ControllerLobbyInfoSchema` (v4).
struct ControllerLobbyInfo: Codable, Equatable, Sendable {
    /// Own character, `nil` (wire `null`) = not chosen yet.
    var character: CharacterId?
    var takenCharacters: [CharacterId]
    /// Optional (older servers omit it).
    var takenBy: [TakenCharacter]?
    var rounds: Int
}

/// `ContextMessageSchema`: replaces the previous context of `slot` completely.
struct Context: Codable, Equatable, Sendable {
    var slot: Int
    var phase: Phase
    var layout: Layout
    var actions: [Action]
    var prompt: Prompt?
    var board: ControllerBoardInfo?
    var minigame: ControllerMinigameInfo?
    var lobby: ControllerLobbyInfo?
}

/// `FeedbackMessageSchema`
struct Feedback: Codable, Equatable, Sendable {
    var slot: Int
    var kind: FeedbackKind
}

/// `ErrorMessageSchema`. Never show `message` to players (ADR-006); map `code` instead.
struct ServerError: Codable, Equatable, Sendable {
    var code: ErrorCode
    var message: String
    /// `seq` of the rejected input, if known.
    var seq: Int?
}

/// `HeartbeatAckMessageSchema`: echoes the client clock `t`.
struct HeartbeatAck: Codable, Equatable, Sendable {
    var t: Double
}

// MARK: - Server → Controller union

enum ProtocolDecodingError: Error, Equatable {
    case tooLarge
    case badMessage(String)
    /// `v` missing is `badMessage`; any other value than `ProtocolConstants.version` is this.
    case versionMismatch(received: String)
}

/// `ServerToControllerMessageSchema` plus forward-compatible `.unknown`.
enum ServerMessage: Equatable, Sendable {
    case welcome(Welcome)
    case context(Context)
    case feedback(Feedback)
    case error(ServerError)
    case heartbeatAck(HeartbeatAck)
    /// Any other `type` (newer server, or a host-only message): ignore, do not fail.
    case unknown(type: String)

    var type: String {
        switch self {
        case .welcome: "welcome"
        case .context: "context"
        case .feedback: "feedback"
        case .error: "error"
        case .heartbeatAck: "heartbeat-ack"
        case .unknown(let type): type
        }
    }

    /// Size → JSON object → version → type → payload, like `parseWith` in `parse.ts`.
    /// Throws `ProtocolDecodingError`; never traps on malformed input.
    static func decode(_ text: String) throws -> ServerMessage {
        guard text.utf16.count <= ProtocolConstants.maxServerMessageLength else {
            throw ProtocolDecodingError.tooLarge
        }
        let data = Data(text.utf8)
        guard
            let object = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
        else { throw ProtocolDecodingError.badMessage("Nachricht ist kein Objekt") }
        guard let version = object["v"] else {
            throw ProtocolDecodingError.badMessage("Protokollversion fehlt")
        }
        guard (version as? NSNumber).map({ !isBool($0) && $0.doubleValue == Double(ProtocolConstants.version) }) == true else {
            throw ProtocolDecodingError.versionMismatch(received: "\(version)")
        }
        guard let type = object["type"] as? String else {
            throw ProtocolDecodingError.badMessage("type fehlt")
        }
        do {
            let decoder = JSONDecoder()
            switch type {
            case "welcome": return .welcome(try decoder.decode(Welcome.self, from: data))
            case "context": return .context(try decoder.decode(Context.self, from: data))
            case "feedback": return .feedback(try decoder.decode(Feedback.self, from: data))
            case "error": return .error(try decoder.decode(ServerError.self, from: data))
            case "heartbeat-ack":
                return .heartbeatAck(try decoder.decode(HeartbeatAck.self, from: data))
            default: return .unknown(type: type)
            }
        } catch {
            throw ProtocolDecodingError.badMessage("Ungültig: \(type)")
        }
    }

    private static func isBool(_ number: NSNumber) -> Bool {
        CFGetTypeID(number) == CFBooleanGetTypeID()
    }
}

extension ServerMessage: Encodable {
    /// Flat encoding (`v`, `type`, payload fields) – only needed for fixture round-trip tests.
    func encode(to encoder: Encoder) throws {
        var envelope = encoder.container(keyedBy: EnvelopeKey.self)
        try envelope.encode(ProtocolConstants.version, forKey: .v)
        try envelope.encode(type, forKey: .type)
        switch self {
        case .welcome(let payload): try payload.encode(to: encoder)
        case .context(let payload): try payload.encode(to: encoder)
        case .feedback(let payload): try payload.encode(to: encoder)
        case .error(let payload): try payload.encode(to: encoder)
        case .heartbeatAck(let payload): try payload.encode(to: encoder)
        case .unknown: break
        }
    }
}

private enum EnvelopeKey: String, CodingKey {
    case v, type
}

// MARK: - Controller → Server

/// Slot input without envelope and without `seq` (TS `SlotIntent` in `net/client.ts`).
/// The client adds `seq`: one counter per connection, strictly increasing across all slots,
/// starting at 1, reset on every new socket.
enum SlotIntent: Equatable, Sendable {
    case ready(slot: Int)
    case move(slot: Int, x: Double, y: Double)
    case press(slot: Int, button: Button)
    case release(slot: Int, button: Button)
    /// Wire type exists (M1 arena); no UI sends it today.
    case gesture(slot: Int, kind: GestureKind)
    /// Wire type exists (M1 arena); board reactions use `choose`.
    case reaction(slot: Int, windowId: Int)
    case choose(slot: Int, promptId: Int, option: String)
    case pickCharacter(slot: Int, character: CharacterId)
    /// Thumbs after a minigame (CHAOS-87, CHAOS-219): `minigameId` and `round` name the run
    /// (`minigame.id`, `board.round`); sending again changes the vote.
    case rate(slot: Int, minigameId: String, round: Int, vote: Vote)

    var slot: Int {
        switch self {
        case .ready(let slot), .move(let slot, _, _), .press(let slot, _),
            .release(let slot, _), .gesture(let slot, _), .reaction(let slot, _),
            .choose(let slot, _, _), .pickCharacter(let slot, _), .rate(let slot, _, _, _):
            slot
        }
    }

    var type: String {
        switch self {
        case .ready: "ready"
        case .move: "move"
        case .press: "press"
        case .release: "release"
        case .gesture: "gesture"
        case .reaction: "reaction"
        case .choose: "choose"
        case .pickCharacter: "pick-character"
        case .rate: "rate"
        }
    }
}

/// `JoinMessageSchema`. `names` is the only way to set a player name (no rename message).
struct Join: Codable, Equatable, Sendable {
    var joinCode: String
    /// iPhone: 1; shared iPad: 2–4 (later step).
    var seats: Int
    /// At most `seats` entries, each `PlayerName.isValid`. Omitted when `nil`.
    var names: [String]?
}

/// `ControllerMessageSchema`: everything a controller sends.
enum ControllerMessage: Equatable, Sendable {
    case join(Join)
    case reconnect(sessionToken: String)
    /// `t` = client clock in ms, only echoed by the server.
    case heartbeat(t: Double)
    case intent(SlotIntent, seq: Int)

    var type: String {
        switch self {
        case .join: "join"
        case .reconnect: "reconnect"
        case .heartbeat: "heartbeat"
        case .intent(let intent, _): intent.type
        }
    }

    /// JSON text for `URLSessionWebSocketTask.Message.string`.
    func encoded() throws -> String {
        String(decoding: try JSONEncoder().encode(self), as: UTF8.self)
    }
}

extension ControllerMessage: Codable {
    private enum Key: String, CodingKey {
        case v, type, joinCode, seats, names, sessionToken, t, slot, seq
        case x, y, button, kind, windowId, promptId, option, character
        case minigameId, round, vote
    }

    func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: Key.self)
        try c.encode(ProtocolConstants.version, forKey: .v)
        try c.encode(type, forKey: .type)
        switch self {
        case .join(let join):
            try c.encode(join.joinCode, forKey: .joinCode)
            try c.encode(join.seats, forKey: .seats)
            try c.encodeIfPresent(join.names, forKey: .names)
        case .reconnect(let token):
            try c.encode(token, forKey: .sessionToken)
        case .heartbeat(let t):
            try c.encode(t, forKey: .t)
        case .intent(let intent, let seq):
            try c.encode(intent.slot, forKey: .slot)
            try c.encode(seq, forKey: .seq)
            switch intent {
            case .ready: break
            case .move(_, let x, let y):
                try c.encode(x, forKey: .x)
                try c.encode(y, forKey: .y)
            case .press(_, let button), .release(_, let button):
                try c.encode(button, forKey: .button)
            case .gesture(_, let kind):
                try c.encode(kind, forKey: .kind)
            case .reaction(_, let windowId):
                try c.encode(windowId, forKey: .windowId)
            case .choose(_, let promptId, let option):
                try c.encode(promptId, forKey: .promptId)
                try c.encode(option, forKey: .option)
            case .pickCharacter(_, let character):
                try c.encode(character, forKey: .character)
            case .rate(_, let minigameId, let round, let vote):
                try c.encode(minigameId, forKey: .minigameId)
                try c.encode(round, forKey: .round)
                try c.encode(vote, forKey: .vote)
            }
        }
    }

    /// Decoding exists for the fixture round-trip tests only.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: Key.self)
        let type = try c.decode(String.self, forKey: .type)
        switch type {
        case "join":
            self = .join(
                Join(
                    joinCode: try c.decode(String.self, forKey: .joinCode),
                    seats: try c.decode(Int.self, forKey: .seats),
                    names: try c.decodeIfPresent([String].self, forKey: .names)))
            return
        case "reconnect":
            self = .reconnect(sessionToken: try c.decode(String.self, forKey: .sessionToken))
            return
        case "heartbeat":
            self = .heartbeat(t: try c.decode(Double.self, forKey: .t))
            return
        default:
            break
        }
        let slot = try c.decode(Int.self, forKey: .slot)
        let seq = try c.decode(Int.self, forKey: .seq)
        let intent: SlotIntent
        switch type {
        case "ready": intent = .ready(slot: slot)
        case "move":
            intent = .move(
                slot: slot, x: try c.decode(Double.self, forKey: .x),
                y: try c.decode(Double.self, forKey: .y))
        case "press": intent = .press(slot: slot, button: try c.decode(Button.self, forKey: .button))
        case "release":
            intent = .release(slot: slot, button: try c.decode(Button.self, forKey: .button))
        case "gesture":
            intent = .gesture(slot: slot, kind: try c.decode(GestureKind.self, forKey: .kind))
        case "reaction":
            intent = .reaction(slot: slot, windowId: try c.decode(Int.self, forKey: .windowId))
        case "choose":
            intent = .choose(
                slot: slot, promptId: try c.decode(Int.self, forKey: .promptId),
                option: try c.decode(String.self, forKey: .option))
        case "pick-character":
            intent = .pickCharacter(
                slot: slot, character: try c.decode(CharacterId.self, forKey: .character))
        case "rate":
            intent = .rate(
                slot: slot, minigameId: try c.decode(String.self, forKey: .minigameId),
                round: try c.decode(Int.self, forKey: .round),
                vote: try c.decode(Vote.self, forKey: .vote))
        default:
            throw DecodingError.dataCorruptedError(
                forKey: .type, in: c, debugDescription: "Unbekannter Controller-Typ \(type)")
        }
        self = .intent(intent, seq: seq)
    }
}

// MARK: - Input helpers (same rules as the zod schemas)

enum JoinCode {
    /// Uppercase, only `A–Z0–9`, at most 8 characters (`normalizeJoinCode` in `config.ts`).
    static func normalize(_ input: String) -> String {
        String(input.uppercased().filter { $0.isASCII && ($0.isLetter || $0.isNumber) }.prefix(8))
    }

    /// `JoinCodeSchema`: `^[A-Z0-9]{4,8}$`.
    static func isValid(_ code: String) -> Bool {
        code.range(of: "^[A-Z0-9]{4,8}$", options: .regularExpression) != nil
    }
}

enum PlayerName {
    /// `PlayerNameSchema`: 1–16 UTF-16 units, no control/bidi characters, no outer whitespace.
    /// An invalid name makes the server reject the whole `join`.
    static func isValid(_ name: String) -> Bool {
        let length = name.utf16.count
        guard length >= 1, length <= ProtocolConstants.maxNameLength else { return false }
        guard name.trimmingCharacters(in: .whitespacesAndNewlines) == name else { return false }
        return !name.unicodeScalars.contains { scalar in
            let v = scalar.value
            return v <= 0x1F || (0x7F...0x9F).contains(v) || (0x202A...0x202E).contains(v)
                || (0x2066...0x2069).contains(v)
        }
    }
}
